import itertools

def is_costas(p):
    n=len(p)
    seen=set()
    for i in range(n):
        for j in range(i+1,n):
            dr=p[j]-p[i]
            dc=j-i
            if (dr,dc) in seen:
                return False
            seen.add((dr,dc))
    return True

